    /* 뷰 초기화 */
    initView: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid;

        var docData = vm.get('docData'),
            gridScheduleInfoItems = vm.get('gridScheduleInfoItems'),
            applyItemList = vm.get('applyItemList'),
            hrWrkmBtrApfId = vm.get('hrWrkmBtrApfId'),
            afterchange = vm.get('afterchange'),
            aprHistId = vm.get('aprHistId'),
            record = vm.get('record'),
            command = vm.get('command'),
            aplDvcdLbl = CodeUtils.getText('HWM009', afterchange.aplDvcd),  // 신청구분
            btrDvcdLbl = CodeUtils.getText('HWM016', afterchange.btrDvcd),  // 출장구분
            btrPeriod = Number(afterchange.btrPeriod),						// 출장일수
            atchFileId = vm.get('atchFileId'),								// 첨부파일 ID
            atchFileNm = vm.get('atchFileNm'),								// 첨부파일명
            atchFileParentId = vm.get('atchFileParentId'),
            totalAmt = 0,													// 총 금액
            viewOption = record.viewOption;									// 출장보고서에서 넘어온 경우 닫기 버튼만 생성하기 위함

        // 뷰 초기화
        refs.rgdt.setHtml(record.rgdt);
        refs.headTitle.setHtml(record.docNm);
        refs.aplDvcdLbl.setValue(aplDvcdLbl);
        refs.btrDvcdLbl.setValue(btrDvcdLbl);
        refs.btrPeriod.setValue(btrPeriod + '일');
        refs.atchFileId.setValue(atchFileId);
        refs.atchFileNm.setValue(atchFileNm);
        refs.atchFileParentId.setValue(atchFileParentId);

        // 첨부파일 유무에 따라 disabled 처리
        if(!atchFileId){
            refs.btnDown.setDisabled(true);
        }
        // 첨부파일 유무에 따라 파일명 처리
        if(!atchFileNm){
            refs.atchFileNm.setValue("첨부파일 없음");
        }else{
            refs.atchFileNm.setValue(atchFileNm);
        }

        // 출장기간/장소 그리드 그리기
        var gridScheduleInfoStore = vm.storeInfo.gridScheduleInfoStore;
        refs.gridScheduleInfo.setStore(gridScheduleInfoStore);
        gridScheduleInfoStore.loadData(gridScheduleInfoItems);

        // 출장자 제목 정보 추가하기
        var sectionBtrEmps = refs.sectionBtrEmps;
        var applyItemListCnt = 0;

        // 출장자 사용금액 정보 뷰 그리기
        for(var i in applyItemList){
            applyItemListCnt++;
            var row = applyItemList[i];
            var rowTotal = 0;
            for(var j in row){
                totalAmt += row[j].subtlAmt;
                rowTotal += row[j].subtlAmt;
            }

            // 출장자 사용금액 컨테이너뷰 추가하기
            refs.btrItems.add({
                xtype : 'HwmBtrAply71MContainer'
            });

            var btrItemsRefs = refs.btrItems.getItems().items[i].innerItems;
            var gridApplyItemStore = Ext.create('Ext.data.Store');

            // 출장자 정보
            btrItemsRefs[0].setHtml('<div style="font-weight:bold">출장자 ' + row[0].hrHrpmEmpId + "/" + row[0].empeNm + '</div>');
            btrItemsRefs[1].setHtml('소계 : ' + me.moneyFormat(rowTotal) + "원");

            // 출장자 사용금액 그리드 그리기
            btrItemsRefs[2].setStore(gridApplyItemStore);

            gridApplyItemStore.removeAll();
            gridApplyItemStore.loadData(row);
        }

        sectionBtrEmps.setHtml('출장자 (총 ' + applyItemListCnt + '명)');

        // 출장자 총 합계
        refs.totalAmt.setHtml('총 합계 : ' + me.moneyFormat(totalAmt) + "원");
    },

    /* 천단위 금액 포매팅 */
    moneyFormat: function(amt) {
        return amt.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    },

    /* 첨부파일 다운로드 버튼 이벤트 */
    onBtnDownTap: function(button, e, eOpts) {
        var me = this,
            refs = me.getReferences(),
            atchFileId = refs.atchFileId.getValue();
        //button.up('#atchFileCon').down('#atchFileIdCon').getValue();

        if (atchFileId) {
            var _url = Property.BASE_URL + Property.DOWN_URL + atchFileId;
            var form = document.createElement("form");
            form.setAttribute("method", "get");
            form.setAttribute("action", _url);
            form.setAttribute("target", "_blank");

            if(!Ext.os.is.Android) {
                // iOS일 경우 safari로 다운로드 처리
                window.open(_url, '_system');
            } else {
                document.body.appendChild(form);
                form.submit();
                document.body.removeChild(form);
            }
        }else{
            Ext.Msg.alert('첨부파일이 없습니다.');
        }
    },

    /* 초기화 */
    Initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid; 		// 결재선 그리드

            var initialConfig = component.initialConfig,
            record = initialConfig.record, 						// 결재함 목록에서 선택한 레코드
            title = initialConfig.title,
            docData = initialConfig.docData,
            aprHistId = initialConfig.aprHistId, 		// 결재내역 ID
            command = initialConfig.command,
            afterchange = docData.afterchange,
            gridScheduleInfoItems = initialConfig.gridScheduleInfo ? initialConfig.gridScheduleInfo.getStore().getData().items : docData.gridScheduleInfo,
            applyItemList = initialConfig.applyItemList ? initialConfig.applyItemList : docData.applyItemList,
            hrWrkmBtrApfId = afterchange.hrWrkmBtrApfId,
            atchFileId = afterchange.atchFileId,
            atchFileNm = afterchange.atchFileNm,
            atchFileParentId = afterchange.atchFileParentId,
            viewOption = record.viewOption;


        /* 화면에서 필요한 데이터 */
        vm.set('docData', docData);
        vm.set('gridScheduleInfoItems', gridScheduleInfoItems);
        vm.set('applyItemList', applyItemList);
        vm.set('hrWrkmBtrApfId', hrWrkmBtrApfId);
        vm.set('afterchange', afterchange);
        vm.set('atchFileId', atchFileId);
        vm.set('atchFileNm', atchFileNm);
        vm.set('atchFileParentId', atchFileParentId);
        /* 화면에서 필요한 데이터 */


        /* 결재에 필요한 데이터 */
        vm.set('aprHistId', aprHistId);
        vm.set('record', record);
        vm.set('command', command);
        /* 결재에 필요한 데이터 */


        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command   : command,
            viewModel : vm,
            aprHistId : aprHistId,
            edocCd    : 'HwmBtrAply71',
            scope     : me
        });


        // 출장보고서에서 넘어온 경우 컨테이너뷰 크기 및 z-index 변경
        if(viewOption == 'search'){
            this.getView().setStyle('z-index:0');
            this.getView().setHeight('80%');
        }

        this.initView();
    },

    /* 출장품의서 닫기 버튼 */
    onCloseBtnTap: function(button, e, eOpts) {
        var me = this,
            view = me.getView();
        view.close();
    },

    /* 컨테이너 뷰가 그려졌을 때 이벤트 */
    onContainerPainted: function(sender, element, eOpts) {
        var me = this,
            refs = me.getReferences(),
            aplCntn = refs.aplCntn;

        // 출장목적 개행 br 처리
        var aplCntn = refs.aplCntn;
        var text = aplCntn.getHtml();
        if(text != null && text != ""){
            text = text.replace(/\n/g,'<br/>');
            aplCntn.setHtml(text);
        }


    }

